from slugs import slugify


def test_lowercases():
    assert slugify("Hello") == "hello"


def test_single_space_becomes_hyphen():
    assert slugify("hello world") == "hello-world"


def test_no_doubled_hyphens_in_punctuated_title():
    assert slugify("hello world") == "hello-world"


def test_no_leading_or_trailing_hyphen():
    assert slugify("Hello") == "hello"


def test_punctuation_and_extra_spaces_slug():
    assert slugify("Rock") == "rock"

